from __future__ import annotations


def dashboard_html(site) -> str:
    return f"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{site.company} Analytics</title>
<style>
:root{{--ink:#17201c;--muted:#63706a;--paper:#f3f0e8;--card:#fff;--green:#174d3a;--gold:#c99b45;--line:#dfe4df;--warn:#9a5b10}}
*{{box-sizing:border-box}}body{{margin:0;background:var(--paper);color:var(--ink);font:15px/1.5 system-ui,-apple-system,sans-serif}}
header{{background:var(--green);color:white;padding:1.1rem max(1.2rem,calc((100vw - 1180px)/2));display:flex;justify-content:space-between;align-items:center;gap:1rem}}header h1{{font:600 1.15rem/1.2 Georgia,serif;margin:0}}header small{{opacity:.75}}
main{{max-width:1180px;margin:0 auto;padding:1.5rem}}.toolbar{{display:flex;align-items:center;justify-content:space-between;gap:1rem;margin-bottom:1rem;flex-wrap:wrap}}select,button,input{{font:inherit;border:1px solid var(--line);border-radius:.55rem;background:white;padding:.55rem .75rem}}button{{cursor:pointer;background:var(--green);color:white;border-color:var(--green)}}
.status{{display:flex;gap:.5rem;align-items:center;color:var(--muted)}}.dot{{width:.65rem;height:.65rem;border-radius:50%;background:var(--warn)}}.dot.ok{{background:#26875d}}
.grid{{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1rem}}.card{{background:var(--card);border:1px solid var(--line);border-radius:.85rem;padding:1rem;box-shadow:0 8px 24px #173d2b0a}}.card h2{{font-size:.76rem;text-transform:uppercase;letter-spacing:.08em;color:var(--muted);margin:0 0 .6rem}}.metric{{font:600 1.9rem/1.1 Georgia,serif}}.delta{{font-size:.8rem;color:var(--muted);margin-top:.35rem}}.wide{{grid-column:span 2}}.full{{grid-column:1/-1}}table{{width:100%;border-collapse:collapse}}th,td{{padding:.6rem .35rem;border-bottom:1px solid var(--line);text-align:left}}th{{color:var(--muted);font-size:.75rem;text-transform:uppercase}}.warning{{color:var(--warn)}}.empty{{padding:2rem;text-align:center;color:var(--muted)}}
@media(max-width:850px){{.grid{{grid-template-columns:repeat(2,minmax(0,1fr))}}}}@media(max-width:520px){{.grid{{grid-template-columns:1fr}}.wide{{grid-column:auto}}header{{align-items:flex-start;flex-direction:column}}}}
</style></head><body>
<header><div><h1>Measurement &amp; Reporting Platform</h1><small>{site.company} · {site.canonical_domain}</small></div><small id="updated">Loading stored reporting data…</small></header>
<main><div class="toolbar"><div><label for="period">Reporting period </label><select id="period"><option value="7d">Last 7 days</option><option value="28d" selected>Last 28 days</option><option value="this_month">This month</option><option value="last_month">Last month</option><option value="90d">Last 90 days</option></select></div><div class="status"><span class="dot" id="dot"></span><span id="health">Checking data health</span><button id="refresh">Refresh</button></div></div>
<section class="grid" id="metrics"></section><section class="grid" style="margin-top:1rem"><article class="card wide"><h2>Confirmed business outcomes</h2><div id="business"></div></article><article class="card wide"><h2>Connected sources</h2><div id="sources"></div></article><article class="card wide"><h2>Paid performance</h2><div id="paid"></div></article><article class="card wide"><h2>Search visibility</h2><div id="search"></div></article><article class="card wide"><h2>Acquisition drivers</h2><div id="acquisition"></div></article><article class="card wide"><h2>Approved funnel</h2><div id="conversion"></div></article><article class="card wide"><h2>Landing pages</h2><div id="pages"></div></article><article class="card wide"><h2>Goals</h2><div id="goals"></div></article><article class="card wide"><h2>Context</h2><div id="annotations"></div></article><article class="card wide"><h2>Freshness</h2><div id="sync"></div><p><a id="pdf" href="#">Download this report as PDF</a></p></article></section></main>
<script>
const site={site.site_id!r};const period=document.querySelector('#period');const fmt=new Intl.NumberFormat();
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[c]));
const table=(heads,rows)=>rows.length?`<table><thead><tr>${{heads.map(x=>`<th>${{x}}</th>`).join('')}}</tr></thead><tbody>${{rows.join('')}}</tbody></table>`:'<div class="empty">A successful query returned no rows for this period.</div>';
const get=async path=>{{const r=await fetch(path,{{headers:sessionStorage.apiToken?{{Authorization:'Bearer '+sessionStorage.apiToken}}:{{}}}});if(!r.ok)throw new Error((await r.json()).detail||r.status);return r.json()}};
function metricCard(m){{let change=m.previousValue===null||m.previousValue===undefined?'No comparable value':m.previousValue===0?(m.value===0?'No change':'New activity'):`${{((m.value-m.previousValue)/Math.abs(m.previousValue)*100).toFixed(1)}}% vs prior`;return `<article class="card"><h2>${{m.metric.replaceAll('_',' ')}}</h2><div class="metric">${{m.value===null?'—':typeof m.value==='number'&&m.metric.endsWith('_rate')?(m.value*100).toFixed(1)+'%':fmt.format(m.value)}}</div><div class="delta">${{change}}</div></article>`}}
async function load(){{document.querySelector('#health').textContent='Loading';try{{const p=period.value;const [o,a,c,l,s,g,n]=await Promise.all([get(`/api/companies/company_house_of_dental/overview?period=${{p}}`),get(`/api/websites/${{site}}/acquisition?period=${{p}}`),get(`/api/websites/${{site}}/conversion?period=${{p}}`),get(`/api/websites/${{site}}/landing-pages?period=${{p}}`),get(`/api/websites/${{site}}/sync-status`),get(`/api/websites/${{site}}/goals`),get(`/api/websites/${{site}}/annotations`)]);const window=o.metrics[0]?.period;const range=`startDate=${{encodeURIComponent(window.start)}}&endDate=${{encodeURIComponent(window.end)}}`;const [sources,business,paid,search]=await Promise.all([get(`/api/websites/${{site}}/external-sources`),get(`/api/websites/${{site}}/business-outcomes?${{range}}`),get(`/api/websites/${{site}}/paid-performance?${{range}}`),get(`/api/websites/${{site}}/search-performance?${{range}}`)]);document.querySelector('#metrics').innerHTML=o.metrics.map(metricCard).join('');document.querySelector('#business').innerHTML=Object.keys(business.outcomes).length?table(['Outcome','Count'],Object.entries(business.outcomes).map(([key,value])=>`<tr><td>${{esc(key.replaceAll('_',' '))}}</td><td>${{fmt.format(value)}}</td></tr>`)):'<div class="empty">Confirmed outcomes are unavailable; GA4 intent is not presented as a booked appointment, customer, or revenue.</div>';document.querySelector('#sources').innerHTML=table(['Source','Status','Last sync'],sources.sources.map(r=>`<tr><td>${{esc(r.source.replaceAll('_',' '))}}</td><td>${{esc(r.status.replaceAll('_',' '))}}</td><td>${{r.lastSyncAt?esc(new Date(r.lastSyncAt).toLocaleString()):'Not available'}}</td></tr>`));document.querySelector('#paid').innerHTML=paid.totals?table(['Cost','Clicks','Impressions'],[`<tr><td>${{esc(paid.totals.currency||'')}} ${{(paid.totals.costMicros/1000000).toFixed(2)}}</td><td>${{fmt.format(paid.totals.clicks)}}</td><td>${{fmt.format(paid.totals.impressions)}}</td></tr>`]):'<div class="empty">Google Ads data is unavailable; this is not a zero.</div>';document.querySelector('#search').innerHTML=search.totals?table(['Clicks','Impressions','CTR','Position'],[`<tr><td>${{fmt.format(search.totals.clicks)}}</td><td>${{fmt.format(search.totals.impressions)}}</td><td>${{(search.totals.ctr*100).toFixed(1)}}%</td><td>${{search.totals.position?.toFixed(1)??'—'}}</td></tr>`]):'<div class="empty">Search Console data is unavailable; this is not a zero.</div>';document.querySelector('#acquisition').innerHTML=table(['Channel','Sessions','Users','Trend'],a.rows.map(r=>`<tr><td>${{esc(r.channel)}}</td><td>${{fmt.format(r.sessions)}}</td><td>${{fmt.format(r.activeUsers)}}</td><td>${{r.sessionChange>=0?'+':''}}${{fmt.format(r.sessionChange)}}</td></tr>`));document.querySelector('#conversion').innerHTML=table(['Stage','Count'],c.funnel.map(r=>`<tr><td>${{esc(r.stage.replaceAll('_',' '))}}</td><td>${{fmt.format(r.value)}}</td></tr>`));document.querySelector('#pages').innerHTML=table(['Page','Sessions','Users','Events'],l.rows.slice(0,10).map(r=>`<tr><td>${{esc(r.landingPage)}}</td><td>${{fmt.format(r.sessions)}}</td><td>${{fmt.format(r.activeUsers)}}</td><td>${{fmt.format(r.eventCount)}}</td></tr>`));document.querySelector('#goals').innerHTML=table(['Metric','Target','Effective'],g.goals.map(r=>`<tr><td>${{esc(r.metric.replaceAll('_',' '))}}</td><td>${{fmt.format(r.target)}}</td><td>${{esc(r.effectiveFrom)}}${{r.effectiveTo?' to '+esc(r.effectiveTo):''}}</td></tr>`));document.querySelector('#annotations').innerHTML=table(['Date','Type','Note'],n.annotations.slice(0,10).map(r=>`<tr><td>${{esc(r.date)}}</td><td>${{esc(r.type.replaceAll('_',' '))}}</td><td>${{esc(r.note)}}</td></tr>`));document.querySelector('#sync').innerHTML=table(['Control','Value'],[['Last successful sync',s.lastSuccessfulSync?new Date(s.lastSuccessfulSync).toLocaleString():'Never'],['Last complete date',s.lastCompleteDate||'None'],['Reporting status',s.status],['Freshness',s.freshness||'Not available']].map(r=>`<tr><td>${{esc(r[0])}}</td><td>${{esc(r[1])}}</td></tr>`));document.querySelector('#pdf').href=`/api/websites/${{site}}/reports/pdf?period=${{p}}`;document.querySelector('#health').textContent=`${{s.status}} · ${{s.freshness||'no freshness'}}`;document.querySelector('#dot').className='dot '+(s.status==='ok'?'ok':'');document.querySelector('#updated').textContent=s.lastSuccessfulSync?'Stored sync '+new Date(s.lastSuccessfulSync).toLocaleString():'No successful stored sync';}}catch(e){{document.querySelector('#metrics').innerHTML='<article class="card full empty">Reporting data is not available yet.</article>';document.querySelector('#health').textContent='Data unavailable';document.querySelector('#updated').textContent='Sync required';}}}}
period.addEventListener('change',load);document.querySelector('#refresh').addEventListener('click',load);load();
</script></body></html>"""


def agency_dashboard_html(site) -> str:
    return f"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Agency Console · Measurement Platform</title>
<style>
:root{{--ink:#17201c;--muted:#63706a;--paper:#f3f0e8;--card:#fff;--green:#174d3a;--gold:#c99b45;--line:#dfe4df;--warn:#9a5b10}}
*{{box-sizing:border-box}}body{{margin:0;background:var(--paper);color:var(--ink);font:15px/1.5 system-ui,-apple-system,sans-serif}}header{{background:var(--green);color:white;padding:1.2rem max(1.2rem,calc((100vw - 1180px)/2));display:flex;justify-content:space-between;gap:1rem;align-items:center}}header h1{{margin:0;font:600 1.25rem Georgia,serif}}header a{{color:white}}main{{max-width:1180px;margin:auto;padding:1.5rem}}.toolbar,.grid{{display:flex;gap:1rem;align-items:center;flex-wrap:wrap}}.grid{{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));align-items:stretch}}.card{{background:var(--card);border:1px solid var(--line);border-radius:.85rem;padding:1rem;box-shadow:0 8px 24px #173d2b0a}}.card h2{{margin:.1rem 0 .3rem;font:600 1.2rem Georgia,serif}}.meta{{color:var(--muted)}}.pill{{display:inline-block;padding:.2rem .5rem;border-radius:99px;background:#e4eee9;color:var(--green);font-size:.78rem}}.warn{{background:#f7ead5;color:var(--warn)}}label{{display:block;font-weight:600;margin-top:.75rem}}input,select,textarea,button{{font:inherit;width:100%;border:1px solid var(--line);border-radius:.5rem;padding:.55rem .65rem}}textarea{{min-height:6rem}}button{{margin-top:1rem;background:var(--green);color:white;cursor:pointer}}#message{{min-height:1.5rem;color:var(--muted)}}ul{{padding-left:1.2rem}}@media(max-width:600px){{header{{align-items:flex-start;flex-direction:column}}}}
</style></head><body>
<header><div><h1>Agency Operations Console</h1><div>{site.company} pilot portfolio</div></div><nav><a href="/dashboard">Client reporting view</a> · <a href="/docs">API docs</a></nav></header>
<main><div class="toolbar"><label for="period">Portfolio period</label><select id="period" style="width:auto"><option>7d</option><option selected>28d</option><option>this_month</option><option>last_month</option><option>90d</option></select><span id="compatibility" class="pill">Loading compatibility…</span></div>
<h2>Portfolio</h2><section id="portfolio" class="grid"></section>
<h2>Google Analytics access</h2><section class="card"><div id="oauth-status" class="meta">Checking OAuth readiness…</div><div id="oauth-connections"></div><button id="oauth-connect" type="button" disabled>Connect read-only Google Analytics</button><div id="oauth-message" class="meta" role="status"></div></section>
<h2>Record an annotation</h2><section class="card"><form id="annotation"><label for="annotation-date">Date</label><input id="annotation-date" type="date" required><label for="annotation-type">Type</label><select id="annotation-type"><option value="site_launch">Site launch</option><option value="campaign_launch">Campaign launch</option><option value="tracking_change">Tracking change</option><option value="website_redesign">Website redesign</option><option value="major_outage">Major outage</option><option value="measurement_change">Measurement change</option></select><label for="annotation-note">Operator note</label><textarea id="annotation-note" maxlength="1000" required></textarea><button>Save annotation</button><div id="message" role="status"></div></form></section>
</main><script>
const site={site.site_id!r};const tokenHeaders=()=>sessionStorage.apiToken?{{Authorization:'Bearer '+sessionStorage.apiToken}}:{{}};const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[c]));
async function request(path,options={{}}){{const response=await fetch(path,{{...options,headers:{{'Content-Type':'application/json',...tokenHeaders(),...(options.headers||{{}})}}}});if(!response.ok)throw new Error((await response.json()).detail||response.status);return response.json()}}
async function load(){{const period=document.querySelector('#period').value;const data=await request('/api/portfolio/summary?period='+encodeURIComponent(period));document.querySelector('#compatibility').textContent=data.measurementCompatibility.replaceAll('_',' ');document.querySelector('#compatibility').className='pill '+(data.measurementCompatibility==='compatible'?'':'warn');document.querySelector('#portfolio').innerHTML=data.websites.map(w=>`<article class="card"><span class="pill ${{w.actionRequired?'warn':''}}">${{w.actionRequired?'Action required':'Healthy'}}</span><h2>${{esc(w.company)}}</h2><div class="meta">${{esc(w.canonicalDomain)}} · ${{esc(w.contract||'No approved contract')}}</div><p><strong>Primary outcome:</strong> ${{w.approvedPrimaryOutcome?esc(w.approvedPrimaryOutcome.value):'Not available'}}</p><p><strong>Period change:</strong> ${{w.periodChange??'Not available'}}<br><strong>Last complete date:</strong> ${{esc(w.lastCompleteDate||'None')}}<br><strong>Sync:</strong> ${{esc(w.syncHealth||'Unknown')}}</p><h3>Open alerts</h3>${{w.alerts.length?'<ul>'+w.alerts.map(a=>`<li>${{esc(a.key)}} (${{esc(a.severity)}})</li>`).join('')+'</ul>':'<p class="meta">No open alerts.</p>'}}</article>`).join('')}}
async function loadOAuth(){{const data=await request('/api/oauth/google/status');const button=document.querySelector('#oauth-connect');const mode=data.productionApproved?'Production approved':'Testing mode · approved test users only';document.querySelector('#oauth-status').innerHTML=`<span class="pill ${{data.configured?'':'warn'}}">${{data.configured?'Ready':'Unavailable'}}</span> ${{esc(mode)}} · scope: <code>analytics.readonly</code>`;document.querySelector('#oauth-connections').innerHTML=data.connections.length?`<ul>${{data.connections.map(connection=>`<li><strong>${{esc(connection.status.replaceAll('_',' '))}}</strong> · connected ${{esc(new Date(connection.connectedAt).toLocaleString())}} · ${{connection.revokedAt?'revoked '+esc(new Date(connection.revokedAt).toLocaleString()):'read-only token stored with Cloud KMS'}}</li>`).join('')}}</ul>`:'<p class="meta">No user OAuth grant has been stored. The existing production ADC assignment remains active.</p>';button.disabled=!data.configured;button.textContent=data.connections.length?'Connect another read-only account':'Connect read-only Google Analytics'}}
document.querySelector('#period').addEventListener('change',()=>load().catch(show));const show=e=>document.querySelector('#message').textContent=e.message||e;
document.querySelector('#oauth-connect').addEventListener('click',async()=>{{const button=document.querySelector('#oauth-connect');button.disabled=true;document.querySelector('#oauth-message').textContent='Preparing a signed, expiring Google authorization request…';try{{const authorization=await request('/api/oauth/google/authorize',{{method:'POST'}});window.location.assign(authorization.authorizationUrl)}}catch(error){{document.querySelector('#oauth-message').textContent=error.message||error;button.disabled=false}}}});
document.querySelector('#annotation-date').value=new Date().toISOString().slice(0,10);document.querySelector('#annotation').addEventListener('submit',async event=>{{event.preventDefault();const body={{date:document.querySelector('#annotation-date').value,type:document.querySelector('#annotation-type').value,note:document.querySelector('#annotation-note').value}};try{{await request(`/api/websites/${{site}}/annotations`,{{method:'POST',body:JSON.stringify(body)}});document.querySelector('#annotation-note').value='';document.querySelector('#message').textContent='Annotation saved.';await load()}}catch(error){{show(error)}}}});load().catch(show);
loadOAuth().catch(error=>{{document.querySelector('#oauth-status').textContent='OAuth status unavailable';document.querySelector('#oauth-message').textContent=error.message||error}});
</script></body></html>"""
